/* ============================================
   RADIO BUTTON COMPONENT
   Custom radio with animated dot indicator
   ============================================ */

.ds-radio {
  display: inline-flex;
  align-items: center;
  gap: var(--gap-200); /* 8px */
  cursor: pointer;
  user-select: none;
}

/* ============================================
   CIRCLE (outer ring)
   ============================================ */

.ds-radio__circle {
  position: relative;
  width: 24px;
  height: 24px;
  border: var(--border-050) solid var(--color-bg-container-border);
  border-radius: var(--radius-pill); /* 999px — perfect circle */
  background-color: var(--color-bg-container-primary-transparent);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  transition: border-color var(--motion-duration-base) var(--motion-ease-standard);
}

/* ============================================
   DOT (inner fill)
   ============================================ */

.ds-radio__dot {
  width: 12px;
  height: 12px;
  border-radius: var(--radius-pill);
  background-color: var(--color-action-primary-bg);
  transform: scale(0);
  transition: transform var(--motion-duration-base) var(--motion-ease-standard);
}

/* ============================================
   LABEL
   ============================================ */

.ds-radio__label {
  font-family: var(--font-paragraph-family);
  font-size: var(--font-paragraph-size);
  font-weight: var(--font-paragraph-weight);
  line-height: var(--font-paragraph-line-height);
  letter-spacing: var(--font-paragraph-letter-spacing);
  color: var(--color-text-primary);
}

/* ============================================
   CHECKED STATE
   ============================================ */

.ds-radio--checked .ds-radio__circle {
  border-color: var(--color-action-primary-bg);
}

.ds-radio--checked .ds-radio__dot {
  transform: scale(1);
}

/* ============================================
   HOVER STATE
   ============================================ */

.ds-radio:not(.ds-radio--disabled):hover .ds-radio__circle {
  border-color: var(--color-action-primary-bg);
}

.ds-radio--checked:not(.ds-radio--disabled):hover .ds-radio__circle {
  border-color: var(--color-action-primary-bg-hover);
}

.ds-radio--checked:not(.ds-radio--disabled):hover .ds-radio__dot {
  background-color: var(--color-action-primary-bg-hover);
}

/* ============================================
   FOCUS STATE
   ============================================ */

.ds-radio:focus-visible .ds-radio__circle {
  outline: var(--border-050) solid var(--color-action-primary-border-tertiary);
  outline-offset: 2px;
}

/* ============================================
   DISABLED STATE
   ============================================ */

.ds-radio--disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

/* ============================================
   RADIO GROUP
   ============================================ */

.ds-radio-group {
  display: flex;
  flex-direction: column;
  gap: var(--gap-200); /* 8px */
}

.ds-radio-group__label {
  font-family: var(--font-paragraph-emphasis-family);
  font-size: var(--font-paragraph-emphasis-size);
  font-weight: var(--font-paragraph-emphasis-weight);
  line-height: var(--font-paragraph-emphasis-line-height);
  letter-spacing: var(--font-paragraph-emphasis-letter-spacing);
  color: var(--color-text-primary);
}

.ds-radio-group__options {
  display: flex;
  flex-direction: column;
  gap: var(--gap-200); /* 8px */
}

.ds-radio-group--horizontal .ds-radio-group__options {
  flex-direction: row;
  gap: var(--gap-500); /* 20px */
}

'use client';

import React from 'react';
import './RadioButton.css';

/** Props owned by RadioButton itself — everything else falls through to the wrapper. */
type RadioButtonOwnProps = {
  /** Label text */
  label?: string;
  /** Whether this radio is selected */
  checked?: boolean;
  /** Whether the radio is disabled */
  disabled?: boolean;
  /** Value for this radio option */
  value?: string;
  /** Called with this radio's value when selected */
  onValueChange?: (value: string) => void;
  /** Additional CSS classes */
  className?: string;
  /**
   * Legacy change handler, kept for backwards compatibility.
   *
   * @deprecated Use `onValueChange` instead.
   */
  onChange?: (value: string) => void;
  /**
   * Legacy accessible-name prop.
   *
   * @deprecated Pass the native `aria-label` attribute instead.
   */
  ariaLabel?: string;
  /**
   * Legacy form-field name.
   *
   * @deprecated No-op. This component renders a `<div role="radio">`, not a
   * native `<input type="radio">`, so it does not group by name or participate
   * in native form submission — `RadioGroup` handles grouping in React state.
   * Declared only so the attribute is not forwarded to an element that rejects it.
   */
  name?: string;
};

export interface RadioButtonProps
  extends RadioButtonOwnProps,
    Omit<React.ComponentPropsWithoutRef<'div'>, keyof RadioButtonOwnProps> {}

export const RadioButton = React.forwardRef<HTMLDivElement, RadioButtonProps>(
  (
    {
      label,
      checked = false,
      disabled = false,
      value = '',
      onValueChange,
      onChange,
      className = '',
      ariaLabel,
      name: _name,
      onClick,
      onKeyDown,
      ...rest
    },
    ref,
  ) => {
    const baseClass = 'ds-radio';

    const classes = [
      baseClass,
      checked ? `${baseClass}--checked` : '',
      disabled ? `${baseClass}--disabled` : '',
      className,
    ]
      .filter(Boolean)
      .join(' ');

    const select = () => {
      if (disabled) return;
      onValueChange?.(value);
      onChange?.(value);
    };

    const handleClick = (e: React.MouseEvent<HTMLDivElement>) => {
      onClick?.(e);
      select();
    };

    const handleKeyDown = (e: React.KeyboardEvent<HTMLDivElement>) => {
      onKeyDown?.(e);
      if (e.key === ' ' || e.key === 'Enter') {
        e.preventDefault();
        select();
      }
    };

    return (
      <div
        {...rest}
        ref={ref}
        className={classes}
        onClick={handleClick}
        onKeyDown={handleKeyDown}
        role="radio"
        aria-checked={checked}
        aria-disabled={disabled}
        aria-label={ariaLabel || rest['aria-label'] || label}
        tabIndex={disabled ? -1 : 0}
      >
        <div className={`${baseClass}__circle`}>
          <div className={`${baseClass}__dot`} />
        </div>
        {label && <span className={`${baseClass}__label`}>{label}</span>}
      </div>
    );
  },
);

RadioButton.displayName = 'RadioButton';

/* ============================================
   RADIO GROUP — Wraps multiple RadioButtons
   ============================================ */

type RadioGroupOwnProps = {
  /** Group label */
  label?: string;
  /** Currently selected value */
  value?: string;
  /** Radio group name */
  name: string;
  /** Radio options */
  options: { label: string; value: string; disabled?: boolean }[];
  /** Layout direction */
  direction?: 'vertical' | 'horizontal';
  /** Called with the newly selected value */
  onValueChange?: (value: string) => void;
  /** Additional CSS classes */
  className?: string;
  /**
   * Legacy change handler, kept for backwards compatibility.
   *
   * @deprecated Use `onValueChange` instead.
   */
  onChange?: (value: string) => void;
};

export interface RadioGroupProps
  extends RadioGroupOwnProps,
    Omit<React.ComponentPropsWithoutRef<'div'>, keyof RadioGroupOwnProps> {}

export const RadioGroup = React.forwardRef<HTMLDivElement, RadioGroupProps>(
  (
    {
      label,
      value,
      name: _name,
      options,
      direction = 'vertical',
      onValueChange,
      onChange,
      className = '',
      ...rest
    },
    ref,
  ) => {
    const baseClass = 'ds-radio-group';
    const classes = [baseClass, `${baseClass}--${direction}`, className]
      .filter(Boolean)
      .join(' ');

    const handleSelect = (next: string) => {
      onValueChange?.(next);
      onChange?.(next);
    };

    return (
      <div {...rest} ref={ref} className={classes} role="radiogroup" aria-label={label}>
        {label && <span className={`${baseClass}__label`}>{label}</span>}
        <div className={`${baseClass}__options`}>
          {options.map((option) => (
            <RadioButton
              key={option.value}
              label={option.label}
              value={option.value}
              checked={value === option.value}
              disabled={option.disabled}
              onValueChange={handleSelect}
            />
          ))}
        </div>
      </div>
    );
  },
);

RadioGroup.displayName = 'RadioGroup';
